run_query_body:
let mut res: u64 = 0;
let mut i: usize = cols.n;
while i > 0
    invariant
        i <= cols.n,
        valid_cols(cols),
        res == method_spec_helper(cols, i as int),
    decreases i,
{
    i = i - 1;
    let a = cols.get_a_exec(i);
    if a > 100 {
        assert(res.wrapping_add(a) == ((res as int + a as int) as u64)) by (bit_vector);
        assert(a == cols.get_a(i as int));
        res = res.wrapping_add(a);
    }
    assert(res == method_spec_helper(cols, i as int));
}
res
